from decimal import Decimal
import pytest


def net_amount(gross, discount):
    gross, discount = Decimal(gross), Decimal(discount)
    if gross < 0 or discount < 0 or discount > gross:
        raise ValueError("invalid amounts")
    return gross - discount


@pytest.mark.parametrize("gross,discount,expected", [
    ("100.00", "10.00", "90.00"),
    ("50.00", "0.00", "50.00"),
    ("0.00", "0.00", "0.00"),
])
def test_net_amount(gross, discount, expected):
    assert net_amount(gross, discount) == Decimal(expected)


def test_discount_cannot_exceed_gross():
    with pytest.raises(ValueError, match="invalid amounts"):
        net_amount("10.00", "11.00")

